                                visited[nr][nc] = True
                                q.append((nr, nc))

                # look for a multi‑colour component that contains the anchor
                comp_counts = Counter(v for _, _, v in cells)
                colours = set(comp_counts.keys())
                if len(colours) <= 1:
                    continue

                # colour that also appears outside this component -> anchor
                candidates = [col for col in colours if total_counts[col] > comp_counts[col]]
                if not candidates:
                    continue
