                anchor_col = min(candidates, key=lambda x: total_counts[x])

                # position of the anchor inside the component
                anchor_pos = None
                for cr, cc, v in cells:
                    if v == anchor_col:
                        anchor_pos = (cr, cc)
                        break
                if anchor_pos is None:
