                ar, ac = anchor_pos

                # shape offsets (colour, offset) relative to anchor
                shape = []
                for cr, cc, v in cells:
                    if v != anchor_col:
                        shape.append((cr - ar, cc - ac, v))

                # decide whether to mirror horizontally
                # look at offsets with dr == 0
                dy_signs = set()
                for dr, dc, _ in shape:
                    if dr == 0:
                        dy_signs.add(1 if dc > 0 else -1 if dc < 0 else 0)
                # if both left and right are present, keep orientation; otherwise mirror
                mirror = not (-1 in dy_signs and 1 in dy_signs)

                if mirror:
                    shape = [(dr, -dc, col) for dr, dc, col in shape]

                # find all solitary anchors (same colour, not belonging to this component)
                comp_set = {(cr, cc) for cr, cc, _ in cells}
                solitary = [(cr, cc) for cr in range(rows) for cc in range(cols)
                            if grid[cr][cc] == anchor_col and (cr, cc) not in comp_set]

                tasks.append({
                    'shape': shape,
                    'solitary': solitary
                })

    # apply all recorded tasks
    for task in tasks:
        shape = task['shape']
